"""Pipeline state machine dispatcher for synaptory — v2 only.

Routes CLI actions to the correct v2 state machine:
  - scrum_state_machine.py  (Scrum lifecycle)
  - kanban_state_machine.py (Kanban lifecycle)
  - spq_state_machine.py    (SPQ lifecycle — Slice/Sync/Checkpoint)
  - story_pipeline.py       (per-story sub-state management)

CLI: python3 state_machine.py <action> <project_dir> [args]
  Actions: init_scrum, init_kanban, init_spq, read
"""

import json
import os
import sys
from typing import Any


def read_state(project_dir: str) -> dict[str, Any]:
    """Read pipeline state from JSON. Returns empty dict if no file."""
    path = os.path.join(
        project_dir, ".synaptory", ".orchestrator", "pipeline-state.json"
    )
    try:
        with open(path, "r") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


if __name__ == "__main__":
    if len(sys.argv) < 3:
        print(
            f"Usage: {sys.argv[0]} <init_scrum|init_kanban|init_spq|read> <project_dir> [args...]",
            file=sys.stderr,
        )
        sys.exit(1)

    action = sys.argv[1]
    project_dir = sys.argv[2]

    if action == "read":
        print(json.dumps(read_state(project_dir), indent=2))

    elif action == "init_scrum":
        try:
            from scrum_state_machine import initialize as scrum_init
            backends_json = sys.argv[3] if len(sys.argv) > 3 else None
            backends = json.loads(backends_json) if backends_json else None
            result = scrum_init(project_dir, backends)
            print(json.dumps(result, indent=2))
        except (ImportError, ValueError) as e:
            print(json.dumps({"error": str(e)}), file=sys.stderr)
            sys.exit(1)

    elif action == "init_kanban":
        try:
            from kanban_state_machine import initialize as kanban_init
            backends_json = sys.argv[3] if len(sys.argv) > 3 else None
            backends = json.loads(backends_json) if backends_json else None
            result = kanban_init(project_dir, backends)
            print(json.dumps(result, indent=2))
        except (ImportError, ValueError) as e:
            print(json.dumps({"error": str(e)}), file=sys.stderr)
            sys.exit(1)

    elif action == "init_spq":
        try:
            from spq_state_machine import initialize as spq_init
            backends_json = sys.argv[3] if len(sys.argv) > 3 else None
            backends = json.loads(backends_json) if backends_json else None
            result = spq_init(project_dir, backends)
            print(json.dumps(result, indent=2))
        except (ImportError, ValueError) as e:
            print(json.dumps({"error": str(e)}), file=sys.stderr)
            sys.exit(1)

    else:
        print(f"Unknown action: {action}", file=sys.stderr)
        sys.exit(1)
